from netmiko import ConnectHandler

pings = {
    'HQ': ('192.168.122.6', [
        'ping 10.10.5.254 source-address 10.10.0.1 count 3',
        'ping 10.10.7.254 source-address 10.10.0.1 count 3',
    ]),
    'Branch1': ('192.168.122.5', [
        'ping 10.10.3.254 source-address 10.10.4.1 count 3',
        'ping 10.10.7.254 source-address 10.10.4.1 count 3',
        'ping 209.165.202.129 count 3',
    ]),
    'Branch2': ('192.168.122.7', [
        'ping 10.10.5.254 source-address 10.10.6.1 count 3',
        'ping 10.10.3.254 source-address 10.10.6.1 count 3',
        'ping 209.165.202.129 count 3',
    ]),
}

for name, (ip, cmds) in pings.items():
    print(f'===== {name} =====')
    dev = ConnectHandler(device_type='vyos', host=ip, username='vyos', password='test')
    for cmd in cmds:
        out = dev.send_command(cmd, read_timeout=15)
        # Just show the summary line
        for line in out.split('\n'):
            if 'packet' in line or 'transmitted' in line:
                print(f'  {cmd.split(\"count\")[0].strip()} -> {line.strip()}')
                break
    dev.disconnect()
